('9f4acea1-58ee-5924-be66-88243093872e','76cb497e-cac6-57b5-82e0-0e440717e7a7',25,'mcq',$q$Nghe câu và chọn nghĩa tiếng Việt đúng.$q$,null,null,$q$我们会尽力做好这份工作。$q$,$q$["Chúng tôi sẽ cố gắng hoàn thành tốt công việc này.", "Con rồng này rất dài.", "Anh ấy cổ vũ các hoạt động bảo vệ môi trường.", "Chúng tôi tiến về phía mục tiêu."]$q$::jsonb,1,$q$尽力$q$,4,null,null),
('745f0e27-7ff7-508f-9fdd-6ccffc06502d','76cb497e-cac6-57b5-82e0-0e440717e7a7',26,'mcq',$q$Nghe câu và chọn nghĩa tiếng Việt đúng.$q$,null,null,$q$她头上有一朵花。$q$,$q$["Anh ấy thể hiện sự nghiêm túc khi đặt câu hỏi.", "Cô ấy có một bông hoa trên đầu.", "Việc vận hành các máy móc này là liên tục.", "Cuối cùng anh ấy đã tìm được công việc."]$q$::jsonb,1,$q$朵$q$,4,null,null),
('a8ff68bc-cae2-57bb-86e2-da9b2c98b0bb','76cb497e-cac6-57b5-82e0-0e440717e7a7',27,'mcq',$q$Nghe câu và chọn nghĩa tiếng Việt đúng.$q$,null,null,$q$他擅长交际。$q$,$q$["Anh ấy giỏi giao tiếp.", "Khu vực này chiếm một diện tích rất lớn.", "Công ty này đã phát triển liên tục kể từ năm 1990.", "Chúng ta đang tụt hậu so với các nước khác."]$q$::jsonb,1,$q$交际$q$,4,null,null),
('6a236ca2-8b10-55fa-ba7e-3837f589cfc0','76cb497e-cac6-57b5-82e0-0e440717e7a7',28,'mcq',$q$Nghe câu và chọn nghĩa tiếng Việt đúng.$q$,null,null,$q$他需要歇一会儿。$q$,$q$["Anh ấy cần nghỉ ngời một lát.", "Câu chuyện này rất sống động.", "Cô ấy cảm thấy rất đau đớn.", "Hai vấn đề này rất giống nhau."]$q$::jsonb,1,$q$歇$q$,4,null,null),
('88469fd8-77d5-5385-b9a5-211ecf4f6220','76cb497e-cac6-57b5-82e0-0e440717e7a7',29,'mcq',$q$Nghe câu và chọn nghĩa tiếng Việt đúng.$q$,null,null,$q$信号不太强，手机信号不好。$q$,$q$["Xin đừng nói chuyện vô ích.", "phái một đội lính để bảo vệ lâu đài.", "Tín hiệu không mạnh, tín hiệu điện thoại không tốt.", "Cô ấy đeo một đôi bông tai đẹp."]$q$::jsonb,1,$q$信号$q$,4,null,null),
('7d7d8fa5-62a3-5f84-ab57-cb2ee6939a27','76cb497e-cac6-57b5-82e0-0e440717e7a7',30,'mcq',$q$Nghe câu và chọn nghĩa tiếng Việt đúng.$q$,null,null,$q$他总是夸奖别人的努力。$q$,$q$["Kế hoạch này rất cụ thể.", "Anh ấy nắm chặt sợi dây.", "Anh ấy luôn khen ngợi nỗ lực của người khác.", "Trong giai đoạn này, nền kinh tế rất không ổn định."]$q$::jsonb,1,$q$夸$q$,4,null,null),
('b1944acc-c80a-597a-b9bc-7d7cbecf4c16','76cb497e-cac6-57b5-82e0-0e440717e7a7',31,'mcq',$q$Nghe câu và chọn nghĩa tiếng Việt đúng.$q$,null,null,$q$两个人要平等对待。$q$,$q$["Cô ấy đang đóng gói hành lý.\n", "Anh ấy khuyên tôi nên nghỉ sớm.", "Cô ấy dồn toàn bộ tâm trí vào công việc.", "Hai người cần được đối xử bình đẳng."]$q$::jsonb,1,$q$平等$q$,4,null,null),
('cf52994a-19e5-50ed-bbb5-75806690be54','76cb497e-cac6-57b5-82e0-0e440717e7a7',32,'mcq',$q$Nghe câu và chọn nghĩa tiếng Việt đúng.$q$,null,null,$q$我的皮肤有点发痒。$q$,$q$["Cô ấy đang mang thai và đang nghỉ ngơi.", "Hệ thống này cần được cải thiện.", "Da của tôi hơi ngứa.", "Mắt phải của nó đã bị mù."]$q$::jsonb,1,$q$痒$q$,4,null,null),
('17bf4703-0e09-59e4-9847-393dbd3d7c18','76cb497e-cac6-57b5-82e0-0e440717e7a7',33,'mcq',$q$Nghe câu và chọn nghĩa tiếng Việt đúng.$q$,null,null,$q$动物园里有一只大象。$q$,$q$["Có một con voi trong vườn thú.", "Anh ấy luôn nói linh tinh.", "Chiều cao của cái bàn này là năm mươi cm.", "Trong ao có rất nhiều cá."]$q$::jsonb,1,$q$大象$q$,4,null,null),
