('2913da5a-47b2-5b34-9766-e1cdde93f7cb','10ceb042-9e15-5b13-943a-76da3b40ac3d',31,'mcq',$q$Chọn nghĩa đúng của câu: 我们需要一个临时的解决方案。$q$,null,null,null,$q$["Tôi thích xem phim hoạt hình.", "Chúng tôi cần một giải pháp tạm thời.", "Anh ấy đã thi đỗ.", "Hiệu suất công việc của anh ấy đã được thăng chức."]$q$::jsonb,1,$q$临时$q$,3,null,null),
('b4e264ea-8484-57c8-84bd-d4549d5b514c','10ceb042-9e15-5b13-943a-76da3b40ac3d',32,'mcq',$q$Chọn nghĩa đúng của câu: 国庆节是中国的重要节日。$q$,null,null,null,$q$["Ngày Quốc khánh là ngày lễ quan trọng của Trung Quốc.", "Chúng ta phải bảo vệ quyền lợi của mình.", "Anh ấy luôn gặp may mắn.", "Chúng ta cần đổi ngoại tệ."]$q$::jsonb,1,$q$国庆节$q$,3,null,null),
('962f2c6f-a166-5e17-a841-6e0ca8e30961','10ceb042-9e15-5b13-943a-76da3b40ac3d',33,'mcq',$q$Chọn nghĩa đúng của câu: 他无奈地摇了摇头。$q$,null,null,null,$q$["Nhà máy đang mở rộng quy mô sản xuất.", "Trong toa tàu rất đông đúc.", "Anh ấy bất lực lắc đầu.", "Chúng tôi đã có một kỳ nghỉ vui vẻ."]$q$::jsonb,1,$q$无奈$q$,3,null,null),
