('0adbf0d9-b828-52a0-a370-cafcfef9d271','10ceb042-9e15-5b13-943a-76da3b40ac3d',35,'mcq',$q$Chọn nghĩa đúng của câu: 我们需要对你的工作进行评价。$q$,null,null,null,$q$["Anh ấy yêu cầu công ty bồi thường cho tổn thất của mình.", "Chúng tôi cần đánh giá công việc của bạn.", "Vấn đề này liên quan đến nội bộ.", "Trời sáng rồi."]$q$::jsonb,1,$q$评价$q$,3,null,null)
